python3 << 'EOF'
import json
for f in ['/logs/agent/fast-agent-home/sessions/2610132247-31aoMg/history_agent.json',
          '/logs/agent/fast-agent-home/sessions/2610132247-31aoMg/history_agent_previous.json']:
    d = json.load(open(f))
    msgs = d['messages']
    print('='*80)
    print(f, 'num messages:', len(msgs))
    for i, m in enumerate(msgs):
        role = m.get('role')
        content = m.get('content')
        if isinstance(content, list):
            parts = []
            for c in content:
                if isinstance(c, dict):
                    if c.get('type') == 'text':
                        parts.append('TEXT:' + c.get('text','')[:150])
                    elif c.get('type') == 'tool_use':
                        parts.append('TOOLUSE:' + c.get('name','') + ' ' + json.dumps(c.get('input',{}))[:200])
                    elif c.get('type') == 'tool_result':
                        parts.append('TOOLRESULT:' + json.dumps(c)[:200])
                    else:
                        parts.append(str(c)[:150])
                else:
                    parts.append(str(c)[:150])
            print(f'--- [{i}] {role}: ' + ' | '.join(parts)[:600])
        else:
            print(f'--- [{i}] {role}: ' + str(content)[:400])
EOF

