cd /tmp && python3 - <<'EOF'
import urllib.request, json, urllib.parse, time
def get(url, timeout=30):
    req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    return urllib.request.urlopen(req, timeout=timeout).read().decode('utf-8','replace')
def search(q):
    url="https://api.github.com/search/repositories?q="+urllib.parse.quote(q)+"&per_page=15"
    try:
        r=json.loads(get(url))
        print("QUERY:", q, "total:", r.get('total_count'))
        for it in r.get('items',[]):
            print("   ", it['full_name'], "|", (it.get('description') or '')[:110])
    except Exception as e:
        print("QUERY:", q, "ERR", e)
    print('-'*70)
queries=["harbor agent evaluation benchmark", "harbor sandbox llm agent", "terminal-bench harbor"]
for q in queries:
    search(q)
    time.sleep(12)
EOF

