echo "== search harbor-datasets full paths for correct.json / grader.py / test_outputs.py =="; grep -c "" /tmp/paths_harborframework_harbor-datasets.txt 2>/dev/null || echo "file missing"; grep -i -E "correct\.json|grader\.py" /tmp/paths_harborframework_harbor-datasets.txt 2>/dev/null | head -40
echo; echo "== search harbor-mix paths =="; grep -i -E "correct\.json|grader\.py" /tmp/paths_harborframework_harbor-mix.txt 2>/dev/null | head -40
echo; echo "== paginate terminal-bench-3.0 =="; python3 - <<'EOF'
import urllib.request, json, re, time
def fetch_tree(repo):
    url=f"https://huggingface.co/api/datasets/{repo}/tree/main?recursive=true&expand=false&limit=1000"
    paths=[]; n=0
    while url and n<60:
        req=urllib.request.Request(url, headers={'User-Agent':'curl/8'})
        with urllib.request.urlopen(req, timeout=60) as r:
            data=json.load(r); link=r.headers.get('Link') or r.headers.get('link')
        for t in data: paths.append(t['path'])
        url=None
        if link:
            m=re.search(r'<([^>]+)>;\s*rel="next"', link)
            if m: url=m.group(1)
        n+=1
    return paths
for repo in ["harborframework/terminal-bench-3.0","harborframework/terminal-bench-2.1"]:
    try:
        p=fetch_tree(repo)
        print(repo,"paths",len(p))
        hits=[x for x in p if re.search(r'floor|plan\.txt|nook|bd1e3aee|correct\.json|grader\.py', x, re.I)]
        for h in hits[:60]: print('  HIT:',h)
    except Exception as e:
        print('ERR',e)
EOF

